import { Button, Slider } from "@mui/material";
import React, { useEffect, useState } from "react";
import Dropdown from "react-bootstrap/Dropdown";
import jsondata from "../json/level1.json";
import parse from "html-react-parser";
import Paper from "@mui/material/Paper";
import { styled } from "@mui/material/styles";
import arrayShuffle from "array-shuffle";
import { DragDropContainer, DropTarget } from "react-drag-drop-container";
import { MdDelete } from "react-icons/md";
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
} from "@material-ui/core";
import DialogContentText from "@mui/material/DialogContentText";
import Tooltip from "@mui/material/Tooltip";
import IconButton from "@mui/material/IconButton";
import { useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { DndProvider, useDrag, useDrop } from "react-dnd";
import { HTML5Backend } from "react-dnd-html5-backend";
import info from "../Images/hint2.png";
import Grid from "@mui/material/Grid";
import { Box } from "@mui/material";
import { toast, ToastContainer } from "react-toastify";
import ReactGA from "react-ga4";
import useWebSocket, { ReadyState } from "react-use-websocket";
import logconfig from "../config/dbconfig.js";
import { SendLogData } from "../config/wslog.js";

function LT2() {
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });
  const [pageName, setPageName] = useState("level 1 page");

  const { t, i18n } = useTranslation();
  const navigate = useNavigate();

  const [mainarr, setMainarr] = useState(
    arrayShuffle(Object.entries(jsondata.data))
  );
  const [punctuations, setPunctuations] = useState(
    arrayShuffle(jsondata.punctuation_marks)
  );
  const [currsent, setCurrsent] = useState();
  const [currsentfeedback, setCurrsentfeedback] = useState();
  const [currfeedback, setCurrfeedback] = useState();
  const [currpuncount, setCurrpuncount] = useState();
  var [sentcount, setSentcount] = useState(0);
  const [table, setTable] = useState(jsondata.table);  

  const [placedPunctuations, setPlacedPunctuations] = useState({});

  const [punctuationFeedback, setPunctuationFeedback] = useState({});

  var [open1, setOpen1] = useState(false);
  var [flag, setFlag] = useState(false);
  var [flag1, setFlag1] = useState(false);
  var [flag2, setFlag2] = useState(false);
  var [flag3, setFlag3] = useState(true);
  var [score, setScore] = useState(0);

  const Item = styled(Paper)(({ theme }) => ({
    backgroundColor: "#F5B946",
    ...theme.typography.body2,
    padding: theme.spacing(1.6),
    textAlign: "center",
    color: theme.palette.text.secondary,
    fontWeight: "bolder",
    fontSize: "20px",
    cursor: "grab",
  }));

  useEffect(() => {
    console.log(mainarr, punctuations);
    if (sentcount >= mainarr.length) {
      setFlag2(true);
    } else {
      setCurrsent(mainarr[sentcount][1].correct_sentence);
      setCurrfeedback(mainarr[sentcount][1].feedback);
      if (currsent != null) {
        console.log(currsent.split(" "));
      }
    }
  }, [sentcount]);

  const level2select = () => {
    ReactGA.event({
      action:
        "English Punctuation mark | CDAC-OlabsNxtG-En-35 | Clicked on level-2 dropdown button.",
      category:
        'English CDAC-OlabsNxtG-En-35 | level-1 "level-2" dropdown button clicked',
      label:
        'English CDAC-OlabsNxtG-En-35 | level-1 "level-2" dropdown button clicked to navigate to level-2.',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      'Level-1 "level-2" dropdown button',
      "Clicked",
      'Level-1 "level-2" dropdown button clicked to navigate to the level-2.'
    );

    navigate("/launchpage/englishactivity/level2");
  };

  const handleDrop = (e, index) => {
    //  alert("index in handleDrop ==>"+ index)
    const droppedMark = e.dragData;
    setPlacedPunctuations((prev) => ({
      ...prev,
      [index]: droppedMark,
    }));
    setFlag1(true);
  };

  const handleverifybtn = () => {
    console.log("placedpunctuations ===>", placedPunctuations);

    if (!flag1) {
      toast.error("Drop the punctuation mark in the blank space(s).", {
        position: "top-center",
        autoClose: 2000,
      });
      return;
    }

    if (!currsent) return;

    const punctuationMarks = punctuations.map((p) => p.mark);
    const originalWords = currsent.split(" ");
    let reconstructedSentence = "";
    let newFeedback = {};
    let punctuationCounter = 0;

    originalWords.forEach((word, wordIndex) => {
      let i = 0;
      punctuationCounter = 0; // reset for each word

      while (i < word.length) {
        const char = word[i];

        if (punctuationMarks.includes(char)) {
          const placeholderKey = `${wordIndex}-${punctuationCounter}`;
          const dropped = placedPunctuations[placeholderKey] || "";

          reconstructedSentence += dropped;

          // feedback
          newFeedback[placeholderKey] =
            dropped === char ? "correct" : "incorrect";

          punctuationCounter++;
          i++; // skip the punctuation
        } else {
          reconstructedSentence += char;
          i++;
        }
      }

      reconstructedSentence += " ";
    });

    reconstructedSentence = reconstructedSentence.trim().replace(/\s+/g, " ");
    const correctSentence = currsent.trim().replace(/\s+/g, " ");

    console.log("Reconstructed:", reconstructedSentence);
    console.log("Expected:", correctSentence);

    setPunctuationFeedback(newFeedback);
    setFlag(true);

    if (reconstructedSentence === correctSentence) {
      setCurrsentfeedback(
        <>
          Correct! &nbsp; <b style={{ color: "green" }}>{currsent}</b> &nbsp; is
          filled with correct punctuation mark(s).
        </>
      );
      setFlag3(false);
    } else {
      setCurrsentfeedback(
        <div style={{ textAlign: "center" }}>
          Incorrect! <b style={{ color: "red" }}>{reconstructedSentence}</b> is
          filled with incorrect punctuation mark(s).
          <br />
          <b>Hint</b>: {currfeedback}
        </div>
      );
    }

     ReactGA.event({
        action:
          "English Punctuation mark | CDAC-OlabsNxtG-En-35 | Clicked on Verify button",
        category: "English CDAC-OlabsNxtG-En-35 | level-1 Verify button clicked",
        label:
          "English CDAC-OlabsNxtG-En-35 | level-1 Verify button clicked for checking dropped punctuation mark.",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        'Level-1 "Verify" button',
        "Clicked",
        'Level-1 "Verify" button clicked for checking dropped punctuation mark.'
      );
  };

  const handlenextbtn = () => {
    if (sentcount >= mainarr.length) {
      setFlag2(true);
    } else {
      sentcount = sentcount + 1;
      setSentcount(sentcount);
      setPlacedPunctuations({});
      setPunctuationFeedback({});
      setFlag(false);
      setFlag1(false);
      setFlag3(true);
      score = score + 1;
      setScore(score);

      ReactGA.event({
        action:
          "English Punctuation mark | CDAC-OlabsNxtG-En-35 | Clicked on Next button",
        category: "English CDAC-OlabsNxtG-En-35 | level-1 Next button clicked",
        label:
          "English CDAC-OlabsNxtG-En-35 | level-1 Next button clicked for next sentence.",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        'Level-1 "Next" button',
        "Clicked",
        'Level-1 "Next" button clicked for next sentence.'
      );
    }
  };

  const handleskipbtn = () => {
    if (sentcount >= mainarr.length) {
      setFlag2(true);
    } else {
      sentcount = sentcount + 1;
      setSentcount(sentcount);
      setPlacedPunctuations({});
      setPunctuationFeedback({});
      setFlag(false);
      setFlag1(false);
      setFlag3(true);

       ReactGA.event({
        action:
          "English Punctuation mark | CDAC-OlabsNxtG-En-35 | Clicked on Skip button",
        category: "English CDAC-OlabsNxtG-En-35 | level-1 Skip button clicked",
        label:
          "English CDAC-OlabsNxtG-En-35 | level-1 Skip button clicked to skip current sentence.",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        'Level-1 "Skip" button',
        "Clicked",
        'Level-1 "Skip" button clicked to skip current sentence.'
      );
    }
  };

  const handleempty = () => {
    setPlacedPunctuations({});
    setPunctuationFeedback({});

     ReactGA.event({
        action:
          "English Punctuation mark | CDAC-OlabsNxtG-En-35 | Clicked on Clear icon.",
        category: "English CDAC-OlabsNxtG-En-35 | level-1 clear icon clicked.",
        label:
          "English CDAC-OlabsNxtG-En-35 | level-1 clear icon clicked to clear the dropped marks.",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        'Level-1 Clear icon',
        "Clicked",
        'Level-1 clear icon clicked to clear the dropped marks.'
      );
  };

  const handleinfobtn = () => {
    setOpen1(true);

    ReactGA.event({
        action:
          "English Punctuation mark | CDAC-OlabsNxtG-En-35 | Clicked on Help icon.",
        category: "English CDAC-OlabsNxtG-En-35 | level-1 help icon clicked.",
        label:
          "English CDAC-OlabsNxtG-En-35 | level-1 help icon clicked for additional punctuation mark information.",
      });

      SendLogData(
        sendJsonMessage,
        pageName,
        'Level-1 Help icon',
        "Clicked",
        'Level-1 help icon clicked for additional punctuation mark information.'
      );
  };

  const handleClose = () => {
    open1 = false;
    setOpen1(open1);
  };

  const restartbtn = () => {
     ReactGA.event({
      action:
        'English Punctuation mark | CDAC-OlabsNxtG-En-35 | Clicked on "Restart" button',
      category: 'English CDAC-OlabsNxtG-En-35 | "Restart" button clicked',
      label:
        'English CDAC-OlabsNxtG-En-35 | "Restart" button clicked and level 1 restarted.',
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      '"Restart" button',
      "Clicked",
      '"Restart" button clicked and level 1 restarted.'
    );

    window.location.reload();
  };

  return (
    <div
      className="scrollbar-primary row d-flex"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        {flag2 ? (
          <div
            className="scrollbar-primary"
            style={{
              height: "80vh",
              width: "95%",
              background: "#FFFFFF 0% 0% no-repeat padding-box",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              padding: "4%",
              paddingTop: "0%",
              overflow: "auto",
              overflowX: "hidden",
              margin: "5px",
              position: "relative",
            }}
          >
            <div className="d-flex justify-content-between align-items-center mb-3">
              <div className="flex-grow-1 text-center">
                <h5>
                  <b>{t("level_1_title")}</b>
                </h5>
              </div>
              <Dropdown className="d-flex justify-content-end">
                <Dropdown.Toggle variant="success" id="dropdown-basic">
                  {t("levels")}
                </Dropdown.Toggle>

                <Dropdown.Menu>
                  <Dropdown.Item href="#/action-1" disabled="true">
                    {t("level_1")}
                  </Dropdown.Item>
                  <Dropdown.Item onClick={level2select}>
                    {t("level_2")}
                  </Dropdown.Item>
                </Dropdown.Menu>
              </Dropdown>
            </div>

            <div
              className="d-flex justify-content-center align-items-center"
              style={{ minHeight: "50vh" }}
            >
              <div
                className="col-sm-6 text-center "
                style={{
                  boxShadow: "rgba(0, 0, 0, 0.24) 0px 3px 8px",
                  padding: "7vh 4vh 7vh 4vh",
                  backgroundColor: "#EDF6FA",
                }}
              >
                <p style={{ fontWeight: "bolder" }}>
                  You have scored {score} out of {mainarr.length} sentences.
                </p>
                <div>
                  <Button variant="contained" onClick={restartbtn}>
                   {t("restart")}
                  </Button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div
            className="scrollbar-primary"
            style={{
              height: "80vh",
              width: "95%",
              background: "#FFFFFF",
              borderRadius: "13px",
              boxShadow: "0px 4px 7px #00000029",
              display: "block",
              padding: "4%",
              paddingTop: "0%",
              overflow: "auto",
              overflowX: "hidden",
              margin: "5px",
              position: "relative",
            }}
          >
            <div className="row-md-auto d-flex text-center">
              <div className="col text-center">
                <h5 style={{ marginTop: "1vh" }}>
                  <b>{t("level_1_title")}</b>
                </h5>
              </div>
              <div className="d-flex justify-content-end">
                <Dropdown className="d-flex justify-content-end">
                  <Dropdown.Toggle variant="success" id="dropdown-basic">
                    {t("levels")}
                  </Dropdown.Toggle>

                  <Dropdown.Menu>
                    <Dropdown.Item href="#/action-1" disabled="true">
                      {t("level_1")}
                    </Dropdown.Item>
                    <Dropdown.Item onClick={level2select}>
                      {t("level_2")}
                    </Dropdown.Item>
                  </Dropdown.Menu>
                </Dropdown>
              </div>
            </div>

            <div
              className="d-flex align-items-center"
              style={{ marginTop: "7%" }}
            >
              <span className="me-3">Sentence</span>
              <Slider
                defaultValue={1}
                step={1}
                min={0}
                max={mainarr.length}
                value={sentcount + 1}
                color="success"
                marks
                valueLabelDisplay="on"
                sx={{
                  "& .MuiSlider-mark": {
                    width: 12,
                    height: 12,
                    borderRadius: "50%",
                  },
                }}
              />
              <span
                className="ms-3"
                style={{
                  height: "40px",
                  width: "60px",
                  borderRadius: "50%",
                  backgroundColor: "lightblue",
                  fontSize: "16px",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                {sentcount + 1}/{mainarr.length}
              </span>
            </div>

            <div
              style={{
                display: "flex",
                justifyContent: "end",
                marginTop: "1vh",
              }}
            >
              <img src={info} title="Help" onClick={handleinfobtn}></img>
            </div>

            <div
              className="row-md-auto"
              style={{
                backgroundColor: "#EDF6FA",
                borderRadius: "13px",
                boxShadow: "0px 4px 7px #00000029",
                display: "flex",
                flexWrap: "wrap",
                justifyContent: "center",
                alignItems: "center",
                padding: "2%",
                paddingRight: "60px", // add space for delete icon
                marginTop: "1vh",
                textAlign: "center",
                position: "relative",
              }}
            >
              {currsent != null
                ? currsent.split(" ").map((word, index) => {
                    let modifiedWord = word;
                    punctuations.forEach((mark) => {
                      if (modifiedWord.includes(mark.mark)) {
                        const regex = new RegExp(`\\${mark.mark}`, "g");
                        modifiedWord = modifiedWord.replace(regex, "_");
                      }
                    });

                    const parts = modifiedWord.split("_");

                    return (
                      <span
                        key={index}
                        style={{
                          margin: "0 5px",
                          fontSize: "18px",
                          whiteSpace: "nowrap",
                        }}
                      >
                        {parts.map((part, i) => {
                          const placeholderIndex = `${index}-${i}`;
                          return (
                            <React.Fragment key={i}>
                              {part && <span>{part}</span>}
                              {i !== parts.length - 1 && (
                                <DropTarget
                                  targetKey="punctuation"
                                  onHit={(e) => handleDrop(e, placeholderIndex)}
                                >
                                  <Box
                                    sx={{
                                      width: 24,
                                      height: 24,
                                      border: "2px dashed #1976d2",
                                      borderRadius: "5px",
                                      display: "inline-block",
                                      mx: "4px",
                                      verticalAlign: "middle",
                                      backgroundColor:
                                        punctuationFeedback[
                                          placeholderIndex
                                        ] === "correct"
                                          ? "#c8e6c9"
                                          : punctuationFeedback[
                                              placeholderIndex
                                            ] === "incorrect"
                                          ? "#ffcdd2"
                                          : "#e3f2fd",
                                      color:
                                        punctuationFeedback[
                                          placeholderIndex
                                        ] === "correct"
                                          ? "green"
                                          : punctuationFeedback[
                                              placeholderIndex
                                            ] === "incorrect"
                                          ? "red"
                                          : "black",
                                      boxShadow: "0 2px 5px rgba(0,0,0,0.1)",
                                      transition: "all 0.3s",
                                      textAlign: "center",
                                      lineHeight: "24px",
                                      fontWeight: "bold",
                                      "&:hover": {
                                        backgroundColor: "#bbdefb",
                                        borderColor: "#1565c0",
                                        cursor: "pointer",
                                      },
                                    }}
                                  >
                                    {placedPunctuations[placeholderIndex] || ""}
                                  </Box>
                                </DropTarget>
                              )}
                            </React.Fragment>
                          );
                        })}
                      </span>
                    );
                  })
                : "no data"}

              {/* Clear Button */}
              <div
                className="delete-icon"
                onClick={handleempty}
                style={{
                  position: "absolute",
                  right: "10px",
                  top: "10px",
                  zIndex: 1,
                }}
              >
                <Tooltip title="Clear">
                  <IconButton>
                    <MdDelete />
                  </IconButton>
                </Tooltip>
              </div>
            </div>

            <div
              className="row-md-auto"
              style={{
                borderRadius: "13px",
                boxShadow: "0px 4px 7px #00000029",
                marginTop: "1vh",
                background: "#EDF6FA",
              }}
            >
              <div style={{ textAlign: "start", paddingTop: "2vh" }}>
                <span style={{ paddingLeft: "5vh" }}>Punctuation marks</span>
              </div>
              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center", // Center contents horizontally
                }}
              >
                <Grid
                  container
                  spacing={{ xs: 2, md: 3 }}
                  justifyContent="center"
                  style={{
                    padding: "15px",
                    maxWidth: "600px", // Optional: controls max width
                  }}
                >
                  {punctuations.length > 0 ? (
                    punctuations.slice(0, 5).map((mark, index) => (
                      <Grid item xs={2} sm={4} md={2} key={index}>
                        <Tooltip title={mark.name} arrow>
                          <span>
                            <DragDropContainer
                              targetKey="punctuation"
                              dragData={mark.mark}
                              onDragStart={() =>
                                console.log(`Dragging ${mark.mark}`)
                              }
                            >
                              <Item>{mark.mark}</Item>
                            </DragDropContainer>
                          </span>
                        </Tooltip>
                      </Grid>
                    ))
                  ) : (
                    <p>No Data in shuffledmarks</p>
                  )}
                </Grid>

                <Grid
                  container
                  spacing={{ xs: 2, md: 3 }}
                  justifyContent="center"
                  style={{
                    marginTop: "5px",
                    padding: "15px",
                    maxWidth: "600px", // Optional
                  }}
                >
                  {punctuations.length > 0 ? (
                    punctuations.slice(5, 8).map((mark, index) => (
                      <Grid item xs={2} sm={4} md={2} key={index}>
                        <Tooltip title={mark.name} arrow>
                          <span>
                            <DragDropContainer
                              targetKey="punctuation"
                              dragData={mark.mark}
                              onDragStart={() =>
                                console.log(`Dragging ${mark.mark}`)
                              }
                            >
                              <Item>{mark.mark}</Item>
                            </DragDropContainer>
                          </span>
                        </Tooltip>
                      </Grid>
                    ))
                  ) : (
                    <p>No Data in shuffledmarks</p>
                  )}
                </Grid>
              </div>
            </div>

            <div className="d-flex justify-content-around mt-4">
              <Button
                variant="contained"
                sx={{ backgroundColor: "#0F477E" }}
                onClick={handleskipbtn}
              >
                Skip
              </Button>
              <Button
                variant="contained"
                sx={{ backgroundColor: "#0F477E" }}
                onClick={handleverifybtn}
              >
                Verify
              </Button>

              <Button
                variant="contained"
                onClick={handlenextbtn}
                sx={{ backgroundColor: "#0F477E" }}
                disabled={flag3}
              >
                Next
              </Button>
            </div>

            <div
              className="row justify-content-center"
              style={{ marginTop: "2vh" }}
            >
              {flag ? (
                <div
                  className="d-flex justify-content-center align-items-center"
                  style={{
                    width: "auto",
                    height: "auto",
                    background: "rgb(255, 255, 255)",
                    boxShadow: "rgba(0, 0, 0, 0.5) 0px 0px 10px",
                    borderRadius: "50px",
                    padding: "1rem",
                  }}
                >
                  {currsentfeedback}
                </div>
              ) : (
                ""
              )}
            </div>
          </div>
        )}
      </div>

      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center"
            style={{
              background: "#002F65",
              borderRadius: "10px 10px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "1.3rem",
              fontWeight: "bolder",
            }}
          >
            {t("instruction")}
          </div>

          <div style={{ maxHeight: "50vh", padding: "2%" }}>
            <div>
              <ul>
                <li>{t("instruction_1_1")}</li>
                <li>{t("instruction_1_2")}</li>
                <li>{t("instruction_1_3")}</li>
                <li>{t("instruction_1_4")}</li>
                <li>{t("instruction_1_5")}</li>
                <li>{t("instruction_1_6")}</li>
                <li>{t("instruction_1_7")}</li>
                <li>{t("instruction_1_8")}</li>
                <li>{t("instruction_1_9")}</li>
                <li>{t("instruction_1_10")}</li>
                <li>{t("instruction_1_11")}</li>
              </ul>
            </div>
          </div>
        </div>
      </div>

      <Dialog
        open={open1}
        onClose={handleClose}
        aria-labelledby="alert-dialog-title"
        aria-describedby="alert-dialog-description"
      >
        <DialogTitle
          id="alert-dialog-title"
          style={{ backgroundColor: "#90D5FF" }}
        >
          Punctuation marks meanings
        </DialogTitle>

        <table style={{ margin: "2vh", border: "1px solid black" }}>
          <tr style={{ textAlign: "center", border: "1px solid black" }}>
            <th style={{ borderRight: "1px solid black" }}>
              Punctuation Marks
            </th>
            <th>Meanings</th>
          </tr>
          {table.length != 0
            ? table.map((item, index) => {
                return (
                  <tr
                    key={index}
                    style={{ textAlign: "center", border: "1px solid black" }}
                  >
                    <td style={{ borderRight: "1px solid black" }}>
                      {item.punctuation}
                    </td>
                    <td>{item.meaning}</td>
                  </tr>
                );
              })
            : ""}
        </table>
        <DialogActions>
          <Button onClick={handleClose} variant="contained">
            Ok
          </Button>
        </DialogActions>
      </Dialog>

      <ToastContainer></ToastContainer>
    </div>
  );
}

export default LT2;
